/* CSS PART 1 OF 2 */

/* DESIGN TOKENS */
:root {
  color-scheme: light;
  --ink: #202c30;
  --ink-soft: #536166;
  --paper: #f6f5f0;
  --white: #ffffff;
  --forest: #294b42;
  --forest-dark: #1c3831;
  --copper: #c4774d;
  --line: #deded5;
  --muted: #858c87;

  --font-display: "DM Serif Display", Georgia, serif;
  --font-body: "DM Sans", "Helvetica Neue", sans-serif;

  --container: 1200px;
  --gutter: clamp(22px, 5vw, 76px);
  --section-space: clamp(76px, 10vw, 132px);

  --radius: 3px;
  --shadow: 0 18px 50px rgba(26, 42, 36, .12);
  --transition: 220ms ease;
}

/* RESET */
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 100px;
}

body {
  margin: 0;
  min-width: 320px;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
select,
textarea {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible,
a:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible {
  outline: 3px solid var(--copper);
  outline-offset: 4px;
}

::selection {
  background: var(--forest);
  color: var(--white);
}

/* TYPOGRAPHY */
h1,
h2,
h3,
h4,
p {
  margin-top: 0;
}

h1,
h2,
h3 {
  font-family: var(--font-display);
  font-weight: 400;
  line-height: 1.12;
  letter-spacing: -.025em;
}

h1 {
  font-size: clamp(3rem, 7.5vw, 6.8rem);
}

h2 {
  font-size: clamp(2.35rem, 5vw, 4.4rem);
}

h3 {
  font-size: clamp(1.65rem, 2.8vw, 2.25rem);
}

p {
  color: var(--ink-soft);
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 22px;
  color: var(--copper);
  font-size: .72rem;
  font-weight: 800;
  letter-spacing: .17em;
  line-height: 1.4;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 30px;
  height: 2px;
  background: currentColor;
  content: "";
}

.section-heading {
  max-width: 760px;
  margin-bottom: 46px;
}

.section-heading h2 {
  margin-bottom: 20px;
}

.section-heading > p {
  max-width: 590px;
  font-size: 1.05rem;
}

/* SHARED LAYOUT */
.container {
  width: min(var(--container), calc(100% - var(--gutter) * 2));
  margin-inline: auto;
}

.section {
  padding-block: var(--section-space);
}

.section--white {
  background: var(--white);
}

.section--forest {
  background: var(--forest);
  color: var(--white);
}

.section--forest p {
  color: rgba(255, 255, 255, .76);
}

.section--forest .eyebrow {
  color: #e4aa85;
}

.section--forest h2,
.section--forest h3 {
  color: var(--white);
}

.section-intro {
  max-width: 670px;
}

/* HEADER AND NAVIGATION */
.site-header {
  position: relative;
  z-index: 20;
  background: var(--paper);
  border-bottom: 1px solid rgba(32, 44, 48, .1);
}

.header-inner {
  width: min(1360px, calc(100% - var(--gutter) * 1.3));
  min-height: 94px;
  margin-inline: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 14px;
  flex-shrink: 0;
}

.brand-logo {
  width: 68px;
  height: 68px;
  object-fit: contain;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  line-height: 1.25;
}

.brand-name {
  color: var(--ink);
  font-family: var(--font-display);
  font-size: 1.1rem;
}

.brand-description {
  margin-top: 5px;
  color: var(--ink-soft);
  font-size: .64rem;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
}

.primary-nav {
  display: flex;
  align-items: center;
  gap: clamp(18px, 3vw, 38px);
}

.primary-nav a:not(.button) {
  position: relative;
  padding-block: 10px;
  color: var(--ink-soft);
  font-size: .83rem;
  font-weight: 700;
  transition: color var(--transition);
}

.primary-nav a:not(.button)::after {
  position: absolute;
  right: 0;
  bottom: 2px;
  left: 0;
  height: 2px;
  background: var(--copper);
  content: "";
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--transition);
}

.primary-nav a:not(.button):hover {
  color: var(--forest);
}

.primary-nav a:not(.button):hover::after {
  transform: scaleX(1);
}

/* BUTTONS */
.button {
  display: inline-flex;
  min-height: 54px;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 14px 24px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  background: var(--forest);
  color: var(--white);
  font-size: .78rem;
  font-weight: 800;
  letter-spacing: .07em;
  text-align: center;
  text-transform: uppercase;
  transition:
    background var(--transition),
    color var(--transition),
    border-color var(--transition),
    transform var(--transition);
}

.button:hover {
  background: var(--forest-dark);
  transform: translateY(-2px);
}

.button--light {
  background: var(--white);
  color: var(--forest-dark);
}

.button--light:hover {
  background: var(--paper);
  color: var(--forest-dark);
}

.button--outline {
  border-color: rgba(255, 255, 255, .65);
  background: transparent;
  color: var(--white);
}

.button--outline:hover {
  border-color: var(--white);
  background: var(--white);
  color: var(--forest-dark);
}

.button--copper {
  background: var(--copper);
  color: var(--white);
}

.button--copper:hover {
  background: #a95e39;
}

/* FULL-BLEED HERO */
.hero {
  position: relative;
  display: flex;
  min-height: min(780px, calc(100svh - 94px));
  align-items: center;
  overflow: hidden;
  isolation: isolate;
  background: var(--forest-dark);
  color: var(--white);
}

.hero-image {
  position: absolute;
  z-index: -2;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 48%;
}

.hero::before {
  position: absolute;
  z-index: -1;
  inset: 0;
  background:
    linear-gradient(
      90deg,
      rgba(19, 34, 30, .91) 0%,
      rgba(19, 34, 30, .76) 43%,
      rgba(19, 34, 30, .22) 100%
    );
  content: "";
}

.hero-content {
  width: min(var(--container), calc(100% - var(--gutter) * 2));
  margin: 0 auto;
  padding-block: 100px 116px;
}

.hero-copy {
  max-width: 790px;
}

.hero .eyebrow {
  color: #edb18b;
}

.hero h1 {
  max-width: 780px;
  margin-bottom: 26px;
  color: var(--white);
}

.hero h1 em {
  color: #e8ae87;
  font-weight: 400;
}

.hero-description {
  max-width: 570px;
  margin-bottom: 34px;
  color: rgba(255, 255, 255, .88);
  font-size: clamp(1rem, 1.5vw, 1.15rem);
  line-height: 1.8;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
}

.hero-caption {
  position: absolute;
  right: var(--gutter);
  bottom: 28px;
  color: rgba(255, 255, 255, .78);
  font-size: .68rem;
  font-weight: 700;
  letter-spacing: .13em;
  text-transform: uppercase;
}

/* TRUST / INTRODUCTION */
.intro-section {
  padding-block: 82px;
  background: var(--white);
}

.intro-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: clamp(40px, 8vw, 110px);
}

.intro-copy h2 {
  max-width: 600px;
}

.intro-copy p {
  max-width: 590px;
}

.intro-statement {
  padding: 34px 0 34px 34px;
  border-left: 3px solid var(--copper);
}

.intro-statement p {
  margin-bottom: 0;
  color: var(--ink);
  font-family: var(--font-display);
  font-size: clamp(1.55rem, 2.5vw, 2.2rem);
  line-height: 1.35;
}

/* WHY CHOOSE US */
.why-section {
  background: var(--forest);
  color: var(--white);
}

.why-layout {
  display: grid;
  grid-template-columns: .9fr 1.1fr;
  gap: clamp(45px, 8vw, 110px);
  align-items: start;
}

.why-copy h2 {
  max-width: 520px;
}

.why-copy p {
  max-width: 440px;
}

.why-points {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0 36px;
  border-top: 1px solid rgba(255, 255, 255, .24);
}

.why-point {
  padding-block: 27px;
  border-bottom: 1px solid rgba(255, 255, 255, .24);
}

.why-point h3 {
  margin-bottom: 11px;
  color: var(--white);
  font-family: var(--font-body);
  font-size: 1rem;
  font-weight: 800;
  letter-spacing: -.01em;
}

.why-point p {
  margin-bottom: 0;
  font-size: .9rem;
  line-height: 1.75;
}

/* ROOF ATTENTION */
.roof-section {
  background: var(--paper);
}

.roof-layout {
  display: grid;
  grid-template-columns: 1fr .85fr;
  align-items: center;
  gap: clamp(42px, 8vw, 100px);
}

.roof-copy h2 {
  max-width: 580px;
}

.roof-copy > p {
  max-width: 570px;
}

.roof-signs {
  margin: 30px 0 34px;
  padding: 0;
  list-style: none;
  border-top: 1px solid var(--line);
}

.roof-signs li {
  position: relative;
  padding: 15px 0 15px 30px;
  border-bottom: 1px solid var(--line);
  color: var(--ink);
  font-size: .94rem;
}

.roof-signs li::before {
  position: absolute;
  top: 25px;
  left: 2px;
  width: 9px;
  height: 9px;
  border: 2px solid var(--copper);
  content: "";
  transform: rotate(45deg);
}

.roof-image-wrap {
  position: relative;
  min-height: 510px;
  background: #d8d9d1;
}

.roof-image {
  width: 100%;
  height: 100%;
  min-height: 510px;
  object-fit: cover;
  object-position: center;
}

.roof-image-note {
  position: absolute;
  right: -18px;
  bottom: 30px;
  max-width: 230px;
  padding: 20px 24px;
  background: var(--white);
  box-shadow: var(--shadow);
  color: var(--ink);
  font-family: var(--font-display);
  font-size: 1.15rem;
  line-height: 1.35;
}

/* COLORADO ROOFING GUIDE */
.guide-section {
  background: var(--white);
}

.guide-layout {
  display: grid;
  grid-template-columns: .8fr 1.2fr;
  gap: clamp(45px, 9vw, 120px);
}

.guide-intro {
  position: sticky;
  top: 35px;
  align-self: start;
}

.guide-intro h2 {
  max-width: 480px;
}

.guide-steps {
  border-top: 1px solid var(--line);
}

.guide-step {
  display: grid;
  grid-template-columns: 65px 1fr;
  gap: 22px;
  padding-block: 28px;
  border-bottom: 1px solid var(--line);
}

.guide-number {
  color: var(--copper);
  font-family: var(--font-display);
  font-size: 2rem;
  line-height: 1.2;
}

.guide-step h3 {
  margin-bottom: 10px;
  font-family: var(--font-body);
  font-size: 1.04rem;
  font-weight: 800;
  letter-spacing: 0;
}

.guide-step p {
  max-width: 570px;
  margin-bottom: 0;
  font-size: .93rem;
}

/* RECENT PROJECTS */
.projects-section {
  background: #eeeee8;
}

.projects-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 35px;
  margin-bottom: 48px;
}

.projects-heading .section-heading {
  margin-bottom: 0;
}

.projects-heading .section-heading h2 {
  max-width: 620px;
}

.projects-grid {
  display: grid;
  grid-template-columns: 1.05fr .95fr;
  gap: 28px;
  align-items: stretch;
}

.project-card {
  min-width: 0;
  background: var(--white);
}

.project-card--featured {
  grid-row: span 2;
}

.project-image-wrap {
  position: relative;
  overflow: hidden;
  background: #d7d9d1;
}

.project-card--featured .project-image-wrap {
  height: 510px;
}

.project-card:not(.project-card--featured) .project-image-wrap {
  height: 240px;
}

.project-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 600ms ease;
}

.project-card:hover .project-image {
  transform: scale(1.035);
}

.project-info {
  padding: 25px 28px 29px;
}

.project-info h3 {
  margin-bottom: 8px;
  font-family: var(--font-display);
  font-size: 1.7rem;
}

.project-info p {
  margin-bottom: 0;
  font-size: .87rem;
}

.project-category {
  display: block;
  margin-bottom: 10px;
  color: var(--copper);
  font-size: .68rem;
  font-weight: 800;
  letter-spacing: .14em;
  text-transform: uppercase;
}

/* MOTION ACCESSIBILITY */
@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: .01ms !important;
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
  }
}
