/* CSS PART 2 OF 2 */

/* CONTACT / CONVERSION */
.contact-section {
  padding-block: var(--section-space);
  background: var(--forest-dark);
  color: var(--white);
}

.contact-layout {
  display: grid;
  grid-template-columns: .85fr 1.15fr;
  gap: clamp(45px, 8vw, 110px);
  align-items: start;
}

.contact-copy h2 {
  max-width: 520px;
  color: var(--white);
}

.contact-copy p {
  max-width: 430px;
  color: rgba(255, 255, 255, .76);
}

.contact-detail {
  margin-top: 35px;
  padding-top: 24px;
  border-top: 1px solid rgba(255, 255, 255, .25);
  color: rgba(255, 255, 255, .85);
  font-size: .9rem;
}

.contact-form {
  padding: clamp(25px, 4vw, 46px);
  background: var(--white);
  color: var(--ink);
  box-shadow: var(--shadow);
}

.contact-form h3 {
  margin-bottom: 28px;
  font-size: 1.9rem;
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.form-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 8px;
}

.form-field--full {
  grid-column: 1 / -1;
}

.form-field label {
  color: var(--ink);
  font-size: .77rem;
  font-weight: 800;
  letter-spacing: .04em;
}

.form-field input,
.form-field select,
.form-field textarea {
  width: 100%;
  min-width: 0;
  min-height: 52px;
  padding: 13px 14px;
  border: 1px solid #d5d9d4;
  border-radius: 2px;
  background: #fbfbf8;
  color: var(--ink);
  transition: border-color var(--transition), box-shadow var(--transition);
}

.form-field textarea {
  min-height: 140px;
  resize: vertical;
}

.form-field input::placeholder,
.form-field textarea::placeholder {
  color: #858d88;
}

.form-field input:focus,
.form-field select:focus,
.form-field textarea:focus {
  border-color: var(--forest);
  outline: 2px solid transparent;
  box-shadow: 0 0 0 3px rgba(41, 75, 66, .14);
}

.form-submit {
  width: 100%;
  margin-top: 25px;
  cursor: pointer;
}

.form-note {
  margin: 15px 0 0;
  color: var(--muted);
  font-size: .76rem;
  line-height: 1.6;
}

/* FOOTER */
.site-footer {
  padding: 55px 0 25px;
  background: #172a25;
  color: var(--white);
}

.footer-main {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 35px;
  padding-bottom: 38px;
}

.footer-brand .brand-name {
  color: var(--white);
}

.footer-brand .brand-description {
  color: rgba(255, 255, 255, .65);
}

.footer-copy {
  max-width: 400px;
  margin: 15px 0 0;
  color: rgba(255, 255, 255, .65);
  font-size: .86rem;
}

.footer-nav {
  display: flex;
  flex-wrap: wrap;
  gap: 14px 28px;
}

.footer-nav a {
  color: rgba(255, 255, 255, .8);
  font-size: .82rem;
  font-weight: 700;
}

.footer-nav a:hover {
  color: #edb18b;
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding-top: 22px;
  border-top: 1px solid rgba(255, 255, 255, .17);
  color: rgba(255, 255, 255, .58);
  font-size: .72rem;
}

/* ACCESSIBLE MOBILE MENU CONTROL */
.menu-toggle {
  display: none;
  width: 46px;
  height: 46px;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 5px;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: 2px;
  background: transparent;
  color: var(--forest-dark);
  cursor: pointer;
}

.menu-toggle span[aria-hidden="true"] {
  display: block;
  width: 20px;
  height: 2px;
  flex: 0 0 2px;
  background-color: currentColor;
}

/* RESPONSIVE: TABLET */
@media (max-width: 1000px) {
  :root {
    --section-space: 84px;
  }

  .header-inner {
    min-height: 82px;
  }

  .brand-logo {
    width: 58px;
    height: 58px;
  }

  .primary-nav {
    gap: 16px;
  }

  .primary-nav a:not(.button) {
    font-size: .76rem;
  }

  .intro-layout,
  .why-layout,
  .roof-layout,
  .guide-layout,
  .contact-layout {
    gap: 42px;
  }

  .roof-image-wrap,
  .roof-image {
    min-height: 430px;
  }

  .projects-grid {
    gap: 20px;
  }

  .project-card--featured .project-image-wrap {
    height: 440px;
  }

  .project-card:not(.project-card--featured) .project-image-wrap {
    height: 210px;
  }
}

/* RESPONSIVE: MOBILE NAVIGATION */
@media (max-width: 760px) {
  :root {
    --gutter: 23px;
    --section-space: 72px;
  }

  html {
    scroll-padding-top: 78px;
  }

  .header-inner {
    position: relative;
    min-height: 76px;
    gap: 14px;
  }

  .brand {
    gap: 10px;
    min-width: 0;
  }

  .brand-logo {
    width: 49px;
    height: 49px;
  }

  .brand-name {
    font-size: .96rem;
  }

  .brand-description {
    font-size: .56rem;
    letter-spacing: .08em;
  }

  .menu-toggle {
    display: flex;
    flex-shrink: 0;
  }

  .primary-nav {
    position: absolute;
    top: calc(100% - 1px);
    right: calc(var(--gutter) * -1);
    left: calc(var(--gutter) * -1);
    display: none;
    max-height: calc(100svh - 76px);
    overflow-y: auto;
    padding: 16px var(--gutter) 24px;
    border-top: 1px solid var(--line);
    border-bottom: 1px solid var(--line);
    background: var(--paper);
    box-shadow: 0 15px 25px rgba(20, 35, 30, .1);
    align-items: stretch;
    flex-direction: column;
    gap: 0;
  }

  .primary-nav.is-open {
    display: flex;
  }

  .primary-nav a:not(.button) {
    display: block;
    width: 100%;
    padding: 13px 2px;
    border-bottom: 1px solid var(--line);
    font-size: .9rem;
  }

  .primary-nav a:not(.button)::after {
    display: none;
  }

  .primary-nav .button {
    width: 100%;
    margin-top: 16px;
  }

  /* HERO */
  .hero {
    min-height: 680px;
    min-height: min(760px, calc(100svh - 76px));
    align-items: end;
  }

  .hero-image {
    object-position: 58% center;
  }

  .hero::before {
    background: linear-gradient(
      0deg,
      rgba(19, 34, 30, .96) 0%,
      rgba(19, 34, 30, .83) 43%,
      rgba(19, 34, 30, .24) 100%
    );
  }

  .hero-content {
    padding-block: 95px 100px;
  }

  .hero h1 {
    font-size: clamp(3rem, 12vw, 4.7rem);
  }

  .hero-description {
    font-size: .98rem;
  }

  .hero-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .hero-actions .button {
    width: 100%;
  }

  .hero-caption {
    right: var(--gutter);
    bottom: 15px;
    font-size: .58rem;
  }

  /* INTRODUCTION */
  .intro-section {
    padding-block: 65px;
  }

  .intro-layout {
    grid-template-columns: 1fr;
    gap: 25px;
  }

  .intro-statement {
    padding: 23px 0 23px 24px;
  }

  /* WHY CHOOSE US */
  .why-layout {
    grid-template-columns: 1fr;
    gap: 30px;
  }

  .why-points {
    grid-template-columns: 1fr;
  }

  .why-point {
    padding-block: 22px;
  }

  /* ROOF */
  .roof-layout {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .roof-image-wrap,
  .roof-image {
    min-height: 0;
    height: 370px;
  }

  .roof-image-note {
    right: 12px;
    bottom: 12px;
    max-width: 190px;
    padding: 15px 17px;
    font-size: 1rem;
  }

  /* GUIDE */
  .guide-layout {
    grid-template-columns: 1fr;
    gap: 30px;
  }

  .guide-intro {
    position: static;
  }

  .guide-step {
    grid-template-columns: 43px 1fr;
    gap: 14px;
    padding-block: 23px;
  }

  .guide-number {
    font-size: 1.7rem;
  }

  /* PROJECTS */
  .projects-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 10px;
  }

  .projects-grid {
    grid-template-columns: 1fr;
    gap: 22px;
  }

  .project-card--featured {
    grid-row: auto;
  }

  .project-card--featured .project-image-wrap,
  .project-card:not(.project-card--featured) .project-image-wrap {
    height: 300px;
  }

  .project-info {
    padding: 22px;
  }

  /* CONTACT */
  .contact-layout {
    grid-template-columns: 1fr;
    gap: 35px;
  }

  .contact-form {
    padding: 26px 21px;
  }

  .form-grid {
    grid-template-columns: 1fr;
    gap: 17px;
  }

  .form-field--full {
    grid-column: auto;
  }

  /* FOOTER */
  .footer-main {
    align-items: flex-start;
    flex-direction: column;
    gap: 28px;
  }

  .footer-nav {
    gap: 13px 22px;
  }

  .footer-bottom {
    align-items: flex-start;
    flex-direction: column;
    gap: 8px;
  }
}

/* RESPONSIVE: SMALL MOBILE */
@media (max-width: 420px) {
  :root {
    --gutter: 19px;
    --section-space: 62px;
  }

  body {
    font-size: 15px;
  }

  .brand-description {
    max-width: 175px;
    font-size: .5rem;
  }

  .hero {
    min-height: 650px;
  }

  .hero h1 {
    font-size: clamp(2.7rem, 12vw, 3.5rem);
  }

  .eyebrow {
    font-size: .65rem;
  }

  .button {
    min-height: 51px;
    padding-inline: 17px;
  }

  .project-card--featured .project-image-wrap,
  .project-card:not(.project-card--featured) .project-image-wrap {
    height: 250px;
  }

  .roof-image-wrap,
  .roof-image {
    height: 300px;
  }

  .contact-form {
    padding: 23px 17px;
  }

  .footer-nav {
    flex-direction: column;
    gap: 13px;
  }
}

/* KEYBOARD FOCUS */
:where(a, button, input, select, textarea, [tabindex]):focus-visible {
  outline: 3px solid var(--copper);
  outline-offset: 4px;
}

.menu-toggle:focus-visible,
.button:focus-visible {
  outline-color: #e7a47c;
  outline-offset: 4px;
}

/* REDUCED MOTION */
@media (prefers-reduced-motion: reduce) {
  html,
  body {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
    scroll-behavior: auto !important;
  }
}
